333: 					return recordErr
334: 				}
335: 				if noticeErr := notifyFailure(requestHead, err.Error()); noticeErr != nil {
336: 					return noticeErr
337: 				}
338: 				refused = append(refused, axi.Object{{Key: "grant", Value: result.Grant}, {Key: "reason", Value: err.Error()}})
339: 				if err := greenhouse.ClearPending(round.Pending); err != nil {
340: 					return err
341: 				}
342: 				continue
343: 			}
344: 			if err != nil {
345: 				if recordErr := recordRequest("failed", result.Grant, time.Now().UnixMilli()); recordErr != nil {
346: 					return recordErr
347: 				}
348: 				return err
349: 			}
350: 			if err := recordRequest("verdict", result.Grant, time.Now().UnixMilli()); err != nil {
351: 				return err
352: 			}
353: 			if err := greenhouse.ClearPending(round.Pending); err != nil {
354: 				return err
355: 			}
356: 			output = append(output, axi.Field{Key: "head", Value: verdict.Head}, axi.Field{Key: "verdict", Value: verdict.Outcome},
357: 				axi.Field{Key: "blocking", Value: verdict.Blocking}, axi.Field{Key: "findings", Value: verdict.FindingsPath}, axi.Field{Key: "recorded", Value: recorded}, axi.Field{Key: "replayed", Value: result.Replayed})
358: 		case greenhouse.Stale:
359: 			if err := recordRequest("head_mismatch", result.Grant, time.Now().UnixMilli()); err != nil {
360: 				return err
361: 			}
362: 			if noticeErr := notifyFailure(requestHead, "the head moved during the review"); noticeErr != nil {
363: 				return noticeErr
364: 			}
365: 			refused = append(refused, axi.Object{{Key: "grant", Value: result.Grant}, {Key: "reason", Value: "the head moved during the review"}})
366: 			if err := greenhouse.ClearPending(round.Pending); err != nil {
367: 				return err
368: 			}
369: 			continue
370: 		case greenhouse.RecoveryRequired:
371: 			if err := recordRequest("failed", result.Grant, time.Now().UnixMilli()); err != nil {
372: 				return err
373: 			}
374: 			if plan == nil || plan.ValidationLoops == nil || plan.ValidationLoops.ReviewParallel != "greenhouse" {
