267: func greenhouseFindingsByHead(ctx context.Context, db *store.DB, projectID int64, requested map[comparisonHead]bool) (map[comparisonHead][]comparisonFinding, error) {
268: 	rows, err := db.QueryContext(ctx, `SELECT r.task_id,r.repo,r.requested_head,v.findings_path FROM greenhouse_review_requests r JOIN verdicts v ON v.id=r.verdict_id WHERE r.project_id=? AND r.outcome='verdict' ORDER BY r.task_id,r.repo,r.requested_head,r.id`, projectID)
269: 	if err != nil {
270: 		return nil, err
271: 	}
272: 	defer rows.Close()
273: 	findingsByHead := map[comparisonHead][]comparisonFinding{}
274: 	seen := map[comparisonHead]map[comparisonFinding]bool{}
275: 	for rows.Next() {
276: 		var key comparisonHead
277: 		var path string
278: 		if err := rows.Scan(&key.TaskID, &key.Repo, &key.Head, &path); err != nil {
279: 			return nil, err
280: 		}
281: 		if !requested[key] {
282: 			continue
283: 		}
284: 		data, err := os.ReadFile(path)
285: 		if err != nil {
286: 			return nil, err
287: 		}
288: 		var findings []comparisonFinding
289: 		if err := json.Unmarshal(data, &findings); err != nil {
290: 			return nil, err
291: 		}
292: 		if seen[key] == nil {
293: 			seen[key] = map[comparisonFinding]bool{}
294: 		}
295: 		for _, finding := range findings {
296: 			if seen[key][finding] {
297: 				continue
298: 			}
299: 			seen[key][finding] = true
300: 			findingsByHead[key] = append(findingsByHead[key], finding)
301: 		}
302: 	}
303: 	return findingsByHead, rows.Err()
304: }
305: 
306: func builtinReviewLatency(ctx context.Context, db *store.DB, projectID int64) (*int64, error) {
307: 	rows, err := db.QueryContext(ctx, `SELECT rr.created_at, (SELECT MIN(s.at) FROM signals s WHERE s.task_id=rr.review_task_id AND s.verb='done') FROM review_rounds rr JOIN tasks t ON t.id=rr.ship_task_id WHERE (?=0 OR t.project_id=?) AND rr.status='verdict'`, projectID, projectID)
308: 	if err != nil {
309: 		return nil, err
310: 	}
311: 	defer rows.Close()
312: 	var values []int64
313: 	for rows.Next() {
314: 		var started int64
315: 		var settled sql.NullInt64
316: 		if err := rows.Scan(&started, &settled); err != nil {
317: 			return nil, err
318: 		}
319: 		if settled.Valid && settled.Int64 >= started {
320: 			values = append(values, settled.Int64-started)
321: 		}
322: 	}
323: 	if err := rows.Err(); err != nil {
324: 		return nil, err
325: 	}
326: 	if len(values) == 0 {
327: 		return nil, nil
328: 	}
329: 	median := medianInt64(values)
330: 	return &median, nil
331: }
