143: func reviewComparisonForProject(ctx context.Context, db *store.DB, project store.Project) (reviewComparisonRow, []int64, error) {
144: 	row := reviewComparisonRow{Project: project.Name, Precision: "not measured in G1", UnmatchedPairs: []string{}}
145: 	requests, err := db.GreenhouseReviewRequests(ctx, project.ID)
146: 	if err != nil {
147: 		return row, nil, err
148: 	}
149: 	headSet := map[string]bool{}
150: 	requestedHeads := map[comparisonHead]bool{}
151: 	latencies := []int64{}
152: 	for _, request := range requests {
153: 		row.Requests++
154: 		requestedHeads[comparisonHead{TaskID: request.TaskID, Repo: request.Repository, Head: request.RequestedHead}] = true
155: 		if request.Outcome == "head_mismatch" {
156: 			row.WrongHead++
157: 		}
158: 		if request.Outcome == "verdict" {
159: 			headSet[fmt.Sprintf("%d/%s/%s/%s", request.TaskID, request.Repository, request.RequestedHead, request.Provider)] = true
160: 			row.Verdicts++
161: 			latencies = append(latencies, request.SettledAt-request.RequestedAt)
162: 			var outcome string
163: 			if err := db.QueryRowContext(ctx, `SELECT verdict FROM verdicts WHERE id=?`, request.VerdictID).Scan(&outcome); err != nil {
164: 				return row, nil, err
165: 			}
166: 			if outcome == "inconclusive" {
167: 				row.Inconclusive++
168: 				row.InconclusiveShare++
169: 			}
170: 		}
171: 	}
172: 	row.ReviewedHeads = len(headSet)
173: 	if row.Requests > 0 {
174: 		row.Reliability = float64(row.Verdicts) / float64(row.Requests)
175: 	}
176: 	if row.Verdicts > 0 {
177: 		row.InconclusiveShare /= float64(row.Verdicts)
178: 	}
179: 	if len(latencies) > 0 {
180: 		median := medianInt64(latencies)
181: 		row.MedianLatencyMS = &median
182: 	}
183: 	if row.Requests > 0 {
184: 		pass := row.Reliability >= 0.95
185: 		row.ReliabilityPass = &pass
186: 	}
187: 	if row.Requests > 0 {
188: 		row.WrongHeadRate = float64(row.WrongHead) / float64(row.Requests)
189: 	}
190: 	wrongPass := row.WrongHead == 0
191: 	row.WrongHeadPass = &wrongPass
192: 	if row.Verdicts > 0 {
193: 		pass := row.InconclusiveShare <= 0.10
194: 		row.InconclusivePass = &pass
195: 	}
196: 	builtinLatency, err := builtinReviewLatency(ctx, db, project.ID)
197: 	if err != nil {
198: 		return row, nil, err
199: 	}
200: 	if builtinLatency != nil {
201: 		row.BuiltinMedianLatencyMS = builtinLatency
202: 		limit := *builtinLatency * 3 / 2
203: 		row.LatencyLimitMS = &limit
204: 		if row.MedianLatencyMS != nil {
205: 			pass := *row.MedianLatencyMS <= limit
206: 			row.LatencyPass = &pass
207: 		}
208: 	}
209: 	findings, err := builtinFixedFindings(ctx, db, project.ID)
210: 	if err != nil {
211: 		return row, nil, err
212: 	}
213: 	parallelByHead, err := greenhouseFindingsByHead(ctx, db, project.ID, requestedHeads)
214: 	if err != nil {
215: 		return row, nil, err
216: 	}
217: 	builtinByHead := map[comparisonHead][]builtinFixedFinding{}
218: 	for _, finding := range findings {
219: 		key := comparisonHead{TaskID: finding.TaskID, Repo: finding.Repo, Head: finding.Head}
220: 		if requestedHeads[key] {
221: 			builtinByHead[key] = append(builtinByHead[key], finding)
222: 		}
223: 	}
224: 	for key, builtins := range builtinByHead {
225: 		row.RecallPairs += len(builtins)
226: 		parallel := parallelByHead[key]
227: 		matchedParallel := make([]bool, len(parallel))
228: 		for _, builtin := range builtins {
229: 			matched := false
230: 			for i, parallelFinding := range parallel {
231: 				if !matchedParallel[i] && parallelFinding.File == builtin.Path && strings.Contains(strings.ToLower(parallelFinding.Explanation), strings.ToLower(builtin.Cause)) {
232: 					matched = true
233: 					matchedParallel[i] = true
234: 					break
235: 				}
236: 			}
237: 			if matched {
238: 				row.RecallMatched++
239: 			} else {
240: 				row.UnmatchedPairs = append(row.UnmatchedPairs, fmt.Sprintf("builtin-only t%d %s@%s: %s", key.TaskID, key.Repo, key.Head, builtin.Path+" | "+builtin.Cause))
241: 			}
242: 		}
243: 		for i, parallelFinding := range parallel {
244: 			if !matchedParallel[i] {
245: 				row.UnmatchedPairs = append(row.UnmatchedPairs, fmt.Sprintf("greenhouse-only t%d %s@%s: %s | %s", key.TaskID, key.Repo, key.Head, parallelFinding.File, parallelFinding.Explanation))
246: 			}
247: 		}
248: 	}
249: 	for key, parallel := range parallelByHead {
250: 		if _, hasBuiltin := builtinByHead[key]; hasBuiltin {
251: 			continue
252: 		}
253: 		for _, finding := range parallel {
254: 			row.UnmatchedPairs = append(row.UnmatchedPairs, fmt.Sprintf("greenhouse-only t%d %s@%s: %s | %s", key.TaskID, key.Repo, key.Head, finding.File, finding.Explanation))
255: 		}
256: 	}
257: 	if row.RecallPairs > 0 {
258: 		recall := float64(row.RecallMatched) / float64(row.RecallPairs)
259: 		row.Recall = &recall
260: 		pass := recall >= 0.90
261: 		row.RecallPass = &pass
262: 	}
263: 	sort.Strings(row.UnmatchedPairs)
264: 	return row, latencies, nil
265: }
