333: func builtinFixedFindings(ctx context.Context, db *store.DB, projectID int64) ([]builtinFixedFinding, error) {
334: 	rows, err := db.QueryContext(ctx, `SELECT f.ship_task_id,f.head_sha,f.repository,f.path,p.root_cause FROM review_findings f JOIN review_patterns p ON p.id=f.pattern_id JOIN tasks t ON t.id=f.ship_task_id WHERE t.project_id=? AND f.origin='introduced' AND f.in_scope=1 AND f.state='fixed' AND f.severity IN ('P0','P1') ORDER BY f.ship_task_id,f.repository,f.head_sha,f.path,f.id`, projectID)
335: 	if err != nil {
336: 		return nil, err
337: 	}
338: 	defer rows.Close()
339: 	var findings []builtinFixedFinding
340: 	for rows.Next() {
341: 		var finding builtinFixedFinding
342: 		if err := rows.Scan(&finding.TaskID, &finding.Head, &finding.Repo, &finding.Path, &finding.Cause); err != nil {
343: 			return nil, err
344: 		}
345: 		findings = append(findings, finding)
346: 	}
347: 	return findings, rows.Err()
348: }
