57: func acquireParallelReviewLock(path string) (*os.File, bool, error) {
58: 	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
59: 		return nil, false, err
60: 	}
61: 	file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o600)
62: 	if err != nil {
63: 		return nil, false, err
64: 	}
65: 	if err := syscall.Flock(int(file.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
66: 		_ = file.Close()
67: 		if errors.Is(err, syscall.EWOULDBLOCK) {
68: 			return nil, true, nil
69: 		}
70: 		return nil, false, err
71: 	}
72: 	return file, false, nil
73: }
