289: 		if err := json.Unmarshal(data, &findings); err != nil {
290: 			return nil, err
291: 		}
292: 		if seen[key] == nil {
293: 			seen[key] = map[comparisonFinding]bool{}
294: 		}
295: 		for _, finding := range findings {
296: 			if seen[key][finding] {
297: 				continue
298: 			}
299: 			seen[key][finding] = true
300: 			findingsByHead[key] = append(findingsByHead[key], finding)
301: 		}
302: 	}
