57: 	}
58: 	if _, err := os.Stat(readyPath); err != nil {
59: 		_ = command.Process.Kill()
60: 		_ = command.Wait()
61: 		t.Fatalf("child did not acquire inherited lock: %v", err)
62: 	}
63: 	if inFlight, err := parallelReviewInFlight(path); err != nil || !inFlight {
64: 		_ = command.Process.Kill()
65: 		_ = command.Wait()
66: 		t.Fatalf("inherited child lock = %v, %v; want active", inFlight, err)
67: 	}
68: 	if err := os.WriteFile(donePath, []byte("done"), 0o600); err != nil {
69: 		_ = command.Process.Kill()
70: 		_ = command.Wait()
71: 		t.Fatal(err)
72: 	}
73: 	if err := command.Wait(); err != nil {
