1018: 		if err := writeParallelReviewOwner(ownerPath, parallelReviewOwner{PID: os.Getpid(), Head: requestHead, RequestedAt: requestStarted}); err != nil {
1019: 			log.Close()
1020: 			_ = releaseParallelReviewLock(lock)
1021: 			if recordErr := recordFailure(err.Error()); recordErr != nil {
1022: 				return recordErr
1023: 			}
1024: 			continue
1025: 		}
1026: 		if err := command.Start(); err != nil {
1027: 			log.Close()
1028: 			_ = releaseParallelReviewLock(lock)
1029: 			if recordErr := recordFailure(err.Error()); recordErr != nil {
1030: 				return recordErr
1031: 			}
1032: 			continue
1033: 		}
1034: 		_ = log.Close()
1035: 		if err := writeParallelReviewOwner(ownerPath, parallelReviewOwner{PID: command.Process.Pid, Head: requestHead, RequestedAt: requestStarted}); err != nil {
